1	// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
2	// Rooms a player can walk into: a flood fill over the cells a player can stand in (two passable cells over a floor),
3	// stepping up one block (a jump, with headroom) or down up to three, through doors and gates, from the entrance
4	// (or from every standable cell on the site's edge). Each room is a box of its inner air; the report says how many of
5	// its standable cells were reached, so a room with no way in, or furniture that walls the floor off, shows up.
6	//   walkReport(grid, { rooms: [{ name, box: [x0,y0,z0,x1,y1,z1] }], entrance: [x,y,z] })
7	const strip = (n) => String(n).replace(/^minecraft:/, "");
8	const PASS = /air$|carpet|redstone_wire|(^|_)rail$|pressure_plate|torch|_button|lever|flower$|tulip|grass$|fern$|sapling|snow$|vine|ladder|_sign$|banner$|tripwire|candle$|light$|structure_void|_door$|fence_gate$|bush$|poppy|dandelion|orchid|allium|bluet|daisy|cornflower|lily_of|wither_rose|azalea$|moss_carpet/;
9	const k = (x, y, z) => `${x},${y},${z}`;
10	
11	export function walkReport(grid, { rooms = [], entrance } = {}) {
12	  const [sx, sy, sz] = grid.size;
13	  const pass = (x, y, z) => !grid.inBounds(x, y, z) ? y >= 0 && y < sy + 2 : PASS.test(strip(grid.blockAt(x, y, z)));
14	  const floor = (x, y, z) => grid.inBounds(x, y, z) && !pass(x, y, z);
15	  const stand = (x, y, z) => grid.inBounds(x, y, z) && pass(x, y, z) && pass(x, y + 1, z) && floor(x, y - 1, z);
16	  let start = [];
17	  if (entrance && stand(...entrance)) start = [entrance];
18	  else {
19	    for (let x = 0; x < sx; x++) for (let z = 0; z < sz; z++) {
20	      if (x !== 0 && z !== 0 && x !== sx - 1 && z !== sz - 1) continue;
21	      for (let y = 1; y < sy; y++) if (stand(x, y, z)) { start.push([x, y, z]); break; }
22	    }
23	  }
24	  const seen = new Set(start.map((p) => k(...p))), q = [...start];
25	  while (q.length) {
26	    const [x, y, z] = q.pop();
27	    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
28	      const nx = x + dx, nz = z + dz;
29	      for (const dy of [0, 1, -1, -2, -3]) {
30	        const ny = y + dy;
31	        if (seen.has(k(nx, ny, nz)) || !stand(nx, ny, nz)) continue;
32	        if (dy === 1 && !pass(x, y + 2, z)) continue;                         // a jump needs headroom where you start
33	        if (dy < 0 && ![...Array(-dy).keys()].every((i) => pass(nx, y - i, nz) && pass(nx, y + 1 - i, nz))) continue;
34	        seen.add(k(nx, ny, nz)); q.push([nx, ny, nz]);
35	        break;                                                                // one landing per column step
36	      }
37	    }
38	  }
39	  const out = rooms.map(({ name, box }) => {
